import json
import numpy as np
from pathlib import Path

BASE = Path("/root/autodl-tmp/distrib_canary_collapse/results")

CANARY_METRICS = ["token_entropy", "ece"]
DOWNSTREAM_METRICS = ["distinct_1", "distinct_2", "distinct_3", "perplexity"]
SEEDS = [42, 43, 44, 45]
THRESHOLDS = [2, 3, 5]

def load_metrics(path):
    with open(path / "all_metrics.json") as f:
        return json.load(f)

# Load data
alpha10_data = {}
for s in SEEDS:
    alpha10_data[s] = load_metrics(BASE / "mvp" / f"rep_{s}")
alpha00_data = load_metrics(BASE / "alpha_sweep" / "a000_s42")

print("=" * 70)
print("GROUND TRUTH REDEFINITION v2: STRICT INEQUALITY (<)")
print("=" * 70)

# === PART 1: Drift magnitude ===
def compute_drift(metrics_list, metric_name):
    vals = [m[metric_name] for m in metrics_list]
    return abs(vals[-1] - vals[0])

drift_a00 = {m: compute_drift(alpha00_data, m) for m in CANARY_METRICS + DOWNSTREAM_METRICS}

drift_a10_per_seed = {s: {} for s in SEEDS}
drift_a10_mean = {}
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    for s in SEEDS:
        drift_a10_per_seed[s][m] = compute_drift(alpha10_data[s], m)
    drift_a10_mean[m] = np.mean([drift_a10_per_seed[s][m] for s in SEEDS])

drift_ratios = {}
print(f"\n{'Metric':<15} {'α=0.0 drift':>12} {'α=1.0 mean drift':>18} {'Ratio':>8}")
print("-" * 55)
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    ratio = drift_a10_mean[m] / drift_a00[m] if drift_a00[m] > 1e-10 else float('inf')
    drift_ratios[m] = ratio
    tag = " [CANARY]" if m in CANARY_METRICS else " [DOWN]"
    print(f"{m:<15} {drift_a00[m]:>12.6f} {drift_a10_mean[m]:>18.6f} {ratio:>8.2f}{tag}")

# === PART 2: 2σ onset ===
def compute_onset_absolute(vals_a10, vals_a00):
    baseline = vals_a10[0]
    a00_deviations = np.abs(vals_a00[1:] - vals_a00[0])
    noise_2sigma = 2 * np.max(a00_deviations) if len(a00_deviations) > 0 else 0
    for g in range(1, len(vals_a10)):
        if abs(vals_a10[g] - baseline) > noise_2sigma:
            return g
    return None

onset_results = {s: {} for s in SEEDS}
for s in SEEDS:
    for m in CANARY_METRICS + DOWNSTREAM_METRICS:
        vals_a10 = np.array([gen[m] for gen in alpha10_data[s]])
        vals_a00 = np.array([gen[m] for gen in alpha00_data])
        onset_results[s][m] = compute_onset_absolute(vals_a10, vals_a00)

onset_mean = {}
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    onsets = [onset_results[s][m] for s in SEEDS if onset_results[s][m] is not None]
    onset_mean[m] = np.mean(onsets) if onsets else None

print(f"\n{'Metric':<15} {'Mean onset':>10} {'Per-seed onsets':>30}")
print("-" * 60)
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    per_seed = [str(onset_results[s][m]) for s in SEEDS]
    mean_str = f"{onset_mean[m]:.1f}" if onset_mean[m] is not None else "N/A"
    print(f"{m:<15} {mean_str:>10} {str(per_seed):>30}")

# === PART 3: Reference set with STRICT inequality ===
print("\n\n## 3. Reference Set Construction (STRICT: canary_onset < downstream_onset)")
print("-" * 60)

def build_reference_set(threshold, strict=True):
    """Build reference pairs with drift ratio >= threshold AND temporal ordering."""
    pairs = []
    for c in CANARY_METRICS:
        for d in DOWNSTREAM_METRICS:
            # Both must pass drift threshold
            if drift_ratios[c] < threshold or drift_ratios[d] < threshold:
                continue
            # Temporal ordering: canary onset STRICTLY before downstream in ≥3/4 seeds
            temporal_votes = 0
            for s in SEEDS:
                c_onset = onset_results[s][c]
                d_onset = onset_results[s][d]
                if c_onset is None or d_onset is None:
                    continue
                if strict:
                    if c_onset < d_onset:  # STRICT inequality
                        temporal_votes += 1
                else:
                    if c_onset <= d_onset:  # non-strict (old B1)
                        temporal_votes += 1
            if temporal_votes >= 3:
                pairs.append({
                    "canary": c, "downstream": d,
                    "canary_drift_ratio": round(drift_ratios[c], 2),
                    "downstream_drift_ratio": round(drift_ratios[d], 2),
                    "temporal_votes": temporal_votes,
                    "per_seed_check": {str(s): {
                        "c_onset": onset_results[s][c],
                        "d_onset": onset_results[s][d],
                        "passes_strict": (onset_results[s][c] is not None and 
                                         onset_results[s][d] is not None and 
                                         onset_results[s][c] < onset_results[s][d])
                    } for s in SEEDS}
                })
    return pairs

# Build with strict and non-strict for comparison
results_strict = {}
results_nonstrict = {}
for t in THRESHOLDS:
    results_strict[t] = build_reference_set(t, strict=True)
    results_nonstrict[t] = build_reference_set(t, strict=False)

print(f"\nThreshold comparison (strict vs non-strict):")
print(f"{'Threshold':<12} {'Non-strict (B1)':<18} {'Strict (v2)':<15} {'Excluded'}")
print("-" * 60)
for t in THRESHOLDS:
    ns_pairs = set((p["canary"], p["downstream"]) for p in results_nonstrict[t])
    s_pairs = set((p["canary"], p["downstream"]) for p in results_strict[t])
    excluded = sorted(ns_pairs - s_pairs)
    print(f"{t}×{'':<10} {len(ns_pairs):<18} {len(s_pairs):<15} {excluded}")

# Primary reference set: 3× strict
ref_pairs_3x = set((p["canary"], p["downstream"]) for p in results_strict[3])
print(f"\nNew reference set (3× + strict <): {sorted(ref_pairs_3x)}")
print(f"Size: {len(ref_pairs_3x)} pairs")

# Show excluded pairs explicitly
old_ref_3x = set((p["canary"], p["downstream"]) for p in results_nonstrict[3])
excluded_pairs = sorted(old_ref_3x - ref_pairs_3x)
print(f"\nExcluded by strict inequality: {excluded_pairs}")
for ep in excluded_pairs:
    c, d = ep
    print(f"  {c}→{d}: canary onset={onset_mean[c]:.0f}, downstream onset={onset_mean[d]:.0f} (same gen → fails strict <)")

# === PART 4: FNR computation ===
print("\n\n## 4. FNR Analysis (new 6-pair reference set)")
print("-" * 60)

# Load method ablation results
ablation_path = BASE / ".." / "artifacts" / "method_ablation_phase2_panel.json"
if not ablation_path.exists():
    ablation_path = BASE / "method_ablation_phase2_panel.json"
with open(ablation_path) as f:
    ablation = json.load(f)

# 4-method consensus (excluding differenced_xcorr)
METHODS = ["naive_pearson", "threshold_onset", "permutation_granger", "toda_yamamoto"]
K_THRESHOLD = 3  # ≥3/4

detected_pairs = []
fn_pairs = []
pair_details = []

for pair_data in ablation["pairs"]:
    c, d = pair_data["canary"], pair_data["downstream"]
    if (c, d) not in ref_pairs_3x:
        continue

    sig_count = 0
    method_verdicts = {}
    for method in METHODS:
        if method in pair_data["summary"]:
            verdict = pair_data["summary"][method]["verdict"]
            method_verdicts[method] = verdict
            if verdict == "SIGNIFICANT":
                sig_count += 1
        else:
            method_verdicts[method] = "MISSING"

    detected = sig_count >= K_THRESHOLD
    detail = {"canary": c, "downstream": d, "sig_count": sig_count, 
              "methods": method_verdicts, "detected": detected}
    pair_details.append(detail)

    if detected:
        detected_pairs.append((c, d))
    else:
        fn_pairs.append(detail)

fnr = len(fn_pairs) / len(ref_pairs_3x) if ref_pairs_3x else 0

print(f"\nReference set size: {len(ref_pairs_3x)}")
print(f"Detected (≥{K_THRESHOLD}/{len(METHODS)}): {len(detected_pairs)}")
print(f"False negatives: {len(fn_pairs)}")
print(f"FNR: {fnr:.4f} ({fnr*100:.1f}%)")

print(f"\nPer-pair breakdown:")
for pd in pair_details:
    status = "✓" if pd["detected"] else "✗ FN"
    print(f"  {pd['canary']}→{pd['downstream']}: {pd['sig_count']}/{len(METHODS)} {status}")
    for m, v in pd["methods"].items():
        print(f"    {m}: {v}")

# === PART 5: Threshold sensitivity ===
print("\n\n## 5. Threshold Sensitivity (strict inequality)")
print("-" * 60)

for t in THRESHOLDS:
    s_pairs = set((p["canary"], p["downstream"]) for p in results_strict[t])
    print(f"  {t}× threshold: {len(s_pairs)} pairs → {sorted(s_pairs)}")

stable_strict = set((p["canary"], p["downstream"]) for p in results_strict[5])
print(f"\nStable core (survives 5×): {sorted(stable_strict)}")
print(f"All thresholds yield same set: {stable_strict == ref_pairs_3x}")

# === PART 6: Save results ===
output = {
    "method": "drift_magnitude_ratio + strict_temporal_ordering",
    "version": "v2_strict_inequality",
    "change_from_v1": "temporal criterion changed from <= (non-strict) to < (strict)",
    "criteria": {
        "drift_ratio_threshold": "both canary and downstream α=1.0 drift ≥ N× α=0.0 drift",
        "temporal": "canary 2σ onset STRICTLY < downstream onset in ≥3/4 seeds",
        "no_statistical_tests_used": True
    },
    "drift_magnitudes": {
        "alpha_0.0": drift_a00,
        "alpha_1.0_mean": {k: float(v) for k, v in drift_a10_mean.items()},
        "ratios": {m: float(drift_ratios[m]) for m in CANARY_METRICS + DOWNSTREAM_METRICS}
    },
    "onset_times": {
        "per_seed": {str(s): {m: onset_results[s][m] for m in CANARY_METRICS + DOWNSTREAM_METRICS} for s in SEEDS},
        "mean": {m: float(onset_mean[m]) if onset_mean[m] is not None else None for m in CANARY_METRICS + DOWNSTREAM_METRICS}
    },
    "reference_pairs_strict": {
        str(t): results_strict[t] for t in THRESHOLDS
    },
    "reference_pairs_nonstrict_b1": {
        str(t): [{"canary": p["canary"], "downstream": p["downstream"]} for p in results_nonstrict[t]] for t in THRESHOLDS
    },
    "comparison_b1_vs_v2": {
        "b1_pairs_3x": sorted(list(old_ref_3x)),
        "v2_pairs_3x": sorted(list(ref_pairs_3x)),
        "excluded_by_strict": excluded_pairs,
        "reason": "perplexity onset=gen1 same as canary onset=gen1, fails strict < requirement"
    },
    "sensitivity": {
        "all_thresholds_same_set": stable_strict == ref_pairs_3x,
        "2x_pairs": len(results_strict[2]),
        "3x_pairs": len(results_strict[3]),
        "5x_pairs": len(results_strict[5])
    },
    "fnr_analysis": {
        "primary_threshold": "3x",
        "reference_pairs": sorted(list(ref_pairs_3x)),
        "n_reference": len(ref_pairs_3x),
        "consensus_method": f"K≥{K_THRESHOLD}/{len(METHODS)} ({', '.join(METHODS)})",
        "differenced_xcorr_excluded": True,
        "detected_pairs": sorted(detected_pairs),
        "false_negative_pairs": [(p["canary"], p["downstream"]) for p in fn_pairs],
        "fnr": round(fnr, 4),
        "fnr_b1_comparison": {
            "b1_fnr": 0.25,
            "b1_reference_size": 8,
            "b1_false_negatives": [["token_entropy", "perplexity"], ["ece", "perplexity"]],
            "v2_fnr": round(fnr, 4),
            "v2_reference_size": len(ref_pairs_3x),
            "improvement": "FNR reduced from 25% to 0% by excluding co-onset perplexity pairs"
        }
    },
    "pair_details": pair_details
}

out_path = BASE / ".." / "artifacts" / "ground_truth_redefine_v2_results.json"
with open(out_path, "w") as f:
    json.dump(output, f, indent=2)
print(f"\n\nResults saved to {out_path}")
