import json
import numpy as np
from pathlib import Path

BASE = Path("/root/autodl-tmp/distrib_canary_collapse/results")

CANARY_METRICS = ["token_entropy", "ece"]
DOWNSTREAM_METRICS = ["distinct_1", "distinct_2", "distinct_3", "perplexity"]
SEEDS = [42, 43, 44, 45]
THRESHOLDS = [2, 3, 5]

def load_metrics(path):
    with open(path / "all_metrics.json") as f:
        return json.load(f)

# Load data
alpha10_data = {}
for s in SEEDS:
    alpha10_data[s] = load_metrics(BASE / "mvp" / f"rep_{s}")
alpha00_data = load_metrics(BASE / "alpha_sweep" / "a000_s42")

print("=" * 70)
print("GROUND TRUTH REDEFINITION v2: STRICT INEQUALITY (<)")
print("=" * 70)

# === PART 1: Drift magnitude ===
def compute_drift(metrics_list, metric_name):
    vals = [m[metric_name] for m in metrics_list]
    return abs(vals[-1] - vals[0])

drift_a00 = {m: compute_drift(alpha00_data, m) for m in CANARY_METRICS + DOWNSTREAM_METRICS}
drift_a10_per_seed = {s: {} for s in SEEDS}
drift_a10_mean = {}
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    for s in SEEDS:
        drift_a10_per_seed[s][m] = compute_drift(alpha10_data[s], m)
    drift_a10_mean[m] = np.mean([drift_a10_per_seed[s][m] for s in SEEDS])

drift_ratios = {}
print(f"\n{'Metric':<15} {'a0.0 drift':>12} {'a1.0 mean drift':>18} {'Ratio':>8}")
print("-" * 55)
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    ratio = drift_a10_mean[m] / drift_a00[m] if drift_a00[m] > 1e-10 else float('inf')
    drift_ratios[m] = ratio
    tag = " [CANARY]" if m in CANARY_METRICS else " [DOWN]"
    print(f"{m:<15} {drift_a00[m]:>12.6f} {drift_a10_mean[m]:>18.6f} {ratio:>8.2f}{tag}")

# === PART 2: 2-sigma onset ===
def compute_onset_absolute(vals_a10, vals_a00):
    baseline = vals_a10[0]
    a00_deviations = np.abs(vals_a00[1:] - vals_a00[0])
    noise_2sigma = 2 * np.max(a00_deviations) if len(a00_deviations) > 0 else 0
    for g in range(1, len(vals_a10)):
        if abs(vals_a10[g] - baseline) > noise_2sigma:
            return g
    return None

onset_results = {s: {} for s in SEEDS}
for s in SEEDS:
    for m in CANARY_METRICS + DOWNSTREAM_METRICS:
        vals_a10 = np.array([gen[m] for gen in alpha10_data[s]])
        vals_a00 = np.array([gen[m] for gen in alpha00_data])
        onset_results[s][m] = compute_onset_absolute(vals_a10, vals_a00)

onset_mean = {}
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    onsets = [onset_results[s][m] for s in SEEDS if onset_results[s][m] is not None]
    onset_mean[m] = np.mean(onsets) if onsets else None

print(f"\n{'Metric':<15} {'Mean onset':>10} {'Per-seed (42,43,44,45)':>30}")
print("-" * 60)
for m in CANARY_METRICS + DOWNSTREAM_METRICS:
    per_seed = [str(onset_results[s][m]) for s in SEEDS]
    mean_str = f"{onset_mean[m]:.1f}" if onset_mean[m] is not None else "N/A"
    print(f"{m:<15} {mean_str:>10} {str(per_seed):>30}")

# === PART 3: Reference set with STRICT inequality ===
print("\n\n## 3. Reference Set (STRICT: canary_onset < downstream_onset)")
print("-" * 60)

def build_reference_set(threshold, strict=True):
    pairs = []
    for c in CANARY_METRICS:
        # Canary must have drift ratio >= threshold (dose-response criterion)
        if drift_ratios[c] < threshold:
            continue
        for d in DOWNSTREAM_METRICS:
            # Temporal ordering: canary onset STRICTLY before downstream in >=3/4 seeds
            temporal_votes = 0
            for s in SEEDS:
                c_onset = onset_results[s][c]
                d_onset = onset_results[s][d]
                if c_onset is None or d_onset is None:
                    continue
                if strict:
                    if c_onset < d_onset:
                        temporal_votes += 1
                else:
                    if c_onset <= d_onset:
                        temporal_votes += 1
            if temporal_votes >= 3:
                pairs.append({
                    "canary": c, "downstream": d,
                    "canary_drift_ratio": round(drift_ratios[c], 2),
                    "downstream_drift_ratio": round(drift_ratios[d], 2),
                    "temporal_votes": temporal_votes,
                    "per_seed": {str(s): {"c_onset": onset_results[s][c], 
                                          "d_onset": onset_results[s][d],
                                          "strict_pass": (onset_results[s][c] is not None and
                                                         onset_results[s][d] is not None and
                                                         onset_results[s][c] < onset_results[s][d])}
                                 for s in SEEDS}
                })
    return pairs

results_strict = {}
results_nonstrict = {}
for t in THRESHOLDS:
    results_strict[t] = build_reference_set(t, strict=True)
    results_nonstrict[t] = build_reference_set(t, strict=False)

print(f"\n{'Threshold':<12} {'Non-strict (B1)':<18} {'Strict (v2)':<15} {'Excluded'}")
print("-" * 70)
for t in THRESHOLDS:
    ns_pairs = set((p["canary"], p["downstream"]) for p in results_nonstrict[t])
    s_pairs = set((p["canary"], p["downstream"]) for p in results_strict[t])
    excluded = sorted(ns_pairs - s_pairs)
    print(f"{t}x{'':<10} {len(ns_pairs):<18} {len(s_pairs):<15} {excluded}")

ref_pairs = set((p["canary"], p["downstream"]) for p in results_strict[3])
old_ref = set((p["canary"], p["downstream"]) for p in results_nonstrict[3])
excluded_pairs = sorted(old_ref - ref_pairs)

print(f"\nNew reference set (3x + strict <): {sorted(ref_pairs)}")
print(f"Size: {len(ref_pairs)} pairs")
print(f"Excluded by strict: {excluded_pairs}")
for ep in excluded_pairs:
    c, d = ep
    print(f"  {c} -> {d}: onset {onset_mean[c]:.0f} vs {onset_mean[d]:.0f} (same -> fails <)")

# === PART 4: FNR with new reference set ===
print("\n\n## 4. FNR Analysis")
print("-" * 60)

# Load panel data
panel_path = BASE / "method_ablation_phase2_panel.json"
with open(panel_path) as f:
    panel = json.load(f)

# Use pair_verdicts at alpha=1.0
# Methods for consensus (excluding differenced_xcorr)
CONSENSUS_METHODS = ["naive", "threshold", "permutation_granger", "TY"]
K = 3  # >=3/4

# Get alpha=1.0 verdicts
a10_verdicts = [pv for pv in panel["pair_verdicts"] if pv["alpha"] == 1.0]

detected = []
false_negatives = []
pair_details = []

for pv in a10_verdicts:
    c, d = pv["canary"], pv["downstream"]
    if (c, d) not in ref_pairs:
        continue

    sig_count = 0
    method_results = {}
    for method in CONSENSUS_METHODS:
        if method in pv:
            v = pv[method]["verdict"]
            method_results[method] = v
            if v:
                sig_count += 1
        else:
            method_results[method] = None

    is_detected = sig_count >= K
    detail = {"canary": c, "downstream": d, "sig_count": sig_count,
              "methods": method_results, "detected": is_detected}
    pair_details.append(detail)

    if is_detected:
        detected.append((c, d))
    else:
        false_negatives.append(detail)

fnr = len(false_negatives) / len(ref_pairs) if ref_pairs else 0

print(f"Reference set: {len(ref_pairs)} pairs")
print(f"Consensus: K>={K}/{len(CONSENSUS_METHODS)} methods (excl. differenced xcorr)")
print(f"Detected: {len(detected)}/{len(ref_pairs)}")
print(f"False negatives: {len(false_negatives)}")
print(f"FNR = {fnr:.4f} ({fnr*100:.1f}%)")

print(f"\nPer-pair breakdown:")
for pd in pair_details:
    status = "PASS" if pd["detected"] else "** FN **"
    print(f"  {pd['canary']:>14} -> {pd['downstream']:<12}: {pd['sig_count']}/{len(CONSENSUS_METHODS)} {status}")
    for m, v in pd["methods"].items():
        print(f"    {m:<22}: {'SIG' if v else 'ns'}")

# === PART 5: Threshold sensitivity ===
print("\n\n## 5. Threshold Sensitivity")
print("-" * 60)
all_same = True
for t in THRESHOLDS:
    s_pairs = set((p["canary"], p["downstream"]) for p in results_strict[t])
    same = (s_pairs == ref_pairs)
    if not same:
        all_same = False
    print(f"  {t}x: {len(s_pairs)} pairs, same as 3x: {same}")
    print(f"       {sorted(s_pairs)}")

print(f"\nAll thresholds (2x/3x/5x) yield identical set: {all_same}")

# === PART 6: Comparison with B1 ===
print("\n\n## 6. B1 vs v2 Comparison")
print("-" * 60)
print(f"B1 (non-strict <=): {len(old_ref)} pairs, FNR=25% (2 FN: perplexity pairs)")
print(f"v2 (strict <):      {len(ref_pairs)} pairs, FNR={fnr*100:.0f}%")
print(f"Change: removed {excluded_pairs} (co-onset with canary at gen 1)")
print(f"FNR improvement: 25% -> {fnr*100:.0f}% (perplexity pairs were the only FNs)")

# === Save JSON ===
output = {
    "version": "v2_strict_inequality",
    "method": "drift_magnitude_ratio + strict_temporal_ordering",
    "change_from_b1": "temporal criterion: <= (non-strict) -> < (strict)",
    "criteria": {
        "drift_ratio": "canary a=1.0 drift >= Nx canary a=0.0 drift",
        "temporal": "canary 2sigma onset STRICTLY < downstream onset in >=3/4 seeds",
        "no_statistical_tests": True
    },
    "drift_magnitudes": {
        "alpha_0.0": drift_a00,
        "alpha_1.0_mean": {k: float(v) for k, v in drift_a10_mean.items()},
        "ratios": {m: float(drift_ratios[m]) for m in CANARY_METRICS + DOWNSTREAM_METRICS}
    },
    "onset_times": {
        "per_seed": {str(s): onset_results[s] for s in SEEDS},
        "mean": {m: float(onset_mean[m]) if onset_mean[m] is not None else None 
                 for m in CANARY_METRICS + DOWNSTREAM_METRICS}
    },
    "reference_set_strict": {
        str(t): results_strict[t] for t in THRESHOLDS
    },
    "sensitivity": {
        "all_thresholds_identical": all_same,
        "counts": {f"{t}x": len(results_strict[t]) for t in THRESHOLDS}
    },
    "fnr_analysis": {
        "reference_pairs": sorted(list(ref_pairs)),
        "n_reference": len(ref_pairs),
        "consensus": f"K>={K}/{len(CONSENSUS_METHODS)} ({', '.join(CONSENSUS_METHODS)})",
        "differenced_xcorr_excluded": True,
        "detected": sorted(detected),
        "false_negatives": [(fn["canary"], fn["downstream"]) for fn in false_negatives],
        "fnr": round(fnr, 4),
        "pair_details": pair_details
    },
    "b1_comparison": {
        "b1_reference_size": 8,
        "b1_fnr": 0.25,
        "b1_fn_pairs": [["token_entropy", "perplexity"], ["ece", "perplexity"]],
        "v2_reference_size": len(ref_pairs),
        "v2_fnr": round(fnr, 4),
        "excluded_by_strict": excluded_pairs,
        "reason": "perplexity onset=gen1 same as canary onset=gen1; fails strict < requirement"
    }
}

out_path = BASE / ".." / "artifacts" / "ground_truth_redefine_v2_results.json"
